SELECT FROM messages m LEFT JOIN users u ON m.SenderUID = u.UID
(m.Title LIKE CONCAT('%', #{keyword}, '%') OR m.Content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY m.CreateTime DESC, m.MID DESC LIMIT #{offset}, #{limit}

